xml.Script:
        Colors[0] := '009600'; // Green
        Colors[1] := 'C80000'; // Red
        Colors[2] := '0000C8'; // Blue
        Colors[3] := 'FF800A'; // Orange

        clYellow := 'FFFF00';
        clWhite  := 'FFFFFF';

        R := 0.5;
        H := R;

        D := R / 3;

        for i := 0 to 39 do begin
            x[i] := R * cos(2 * Pi / 40 * i);
            y[i] := R * sin(2 * Pi / 40 * i);
        end;

        function FromTo(iFrom, iTo);
        begin
            Result := IntToStr(iFrom);
            for i := iFrom + 1 to iTo do
                Result := Result + ';' + IntToStr(i);
            for i := iFrom - 1 downto iTo do
                Result := Result + ';' + IntToStr(i);
        end;

Macro.Script:
i1 := i;
i2 := (i + 1) mod 40;
Color := Colors[(i+35) mod 40 div 10];
Inc(i);
